function activateMenuRequest(id){const request=data.menuRequests.find(row=>row.id===id),existing=data.menuEntitlements.find(row=>row.ownerId===request?.ownerId);if(!request)return;const defaultMonths=Number(request.months)||1;modal('Activate Restaurant Plan',`<form id="activateMenuPlan"><p><strong>${esc(request.ownerEmail||request.ownerId)}</strong> requested ${esc(request.plan)} for ${esc(request.periodLabel||defaultMonths+' month(s)')}.</p><div class="form-grid"><div class="field"><label>Plan</label><select name="plan"><option value="standard" ${request.plan!=='premium'?'selected':''}>Standard</option><option value="premium" ${request.plan==='premium'?'selected':''}>Premium</option></select></div><div class="field"><label>Restaurant limit</label><input name="maxRestaurants" type="number" min="1" step="1" value="${Number(existing?.maxRestaurants)||5}" required></div><div class="field"><label>Activation months</label><input name="months" type="number" min="1" max="120" value="${defaultMonths}" required></div></div><label class="notice"><input name="lifetime" type="checkbox" ${existing?.lifetime?'checked':''}> Lifetime access — subscription never expires</label><button class="btn green full">Activate Account</button></form>`,()=>{$('#activateMenuPlan').onsubmit=async event=>{event.preventDefault();const fd=new FormData(event.target),values=Object.fromEntries(fd),months=Number(values.months),base=Math.max(Date.now(),new Date(existing?.expiresAt||0).getTime()),expiry=new Date(base);expiry.setMonth(expiry.getMonth()+months);const payload={ownerId:request.ownerId,ownerEmail:request.ownerEmail||'',ownerName:request.ownerName||'',plan:values.plan,maxRestaurants:Number(values.maxRestaurants),restaurantPacks:Math.max(1,Math.ceil(Number(values.maxRestaurants)/5)),lifetime:fd.has('lifetime'),expiresAt:fd.has('lifetime')?'':expiry.toISOString(),activatedAt:existing?.activatedAt||now(),updatedAt:now()};try{let entitlement;if(existing)entitlement=await api.update('digital_menu_entitlements',existing.id,payload);else entitlement=await api.create('digital_menu_entitlements',payload,`dm-${String(request.ownerId).slice(0,30)}`,api.managedPermissionSet?.()||api.collaborativePermissionSet(request.ownerId));await api.update('digital_menu_requests',id,{status:'Activated',activatedAt:now(),entitlementId:entitlement.id||entitlement.$id});closeModal();await refresh();toast('Restaurant plan activated')}catch(error){toast(error.message||'Could not activate restaurant plan')}}})}
