function normaliseDinerPhone(value){return String(value||'').replace(/\D/g,'')}
function dinerIndiaDate(value){return new Date(value||Date.now()).toLocaleDateString('en-CA',{timeZone:'Asia/Kolkata'})}
function dinerOrderKind(ownerId){return `digital_order_${String(ownerId).replace(/[^a-zA-Z0-9._-]/g,'-').slice(0,47)}`}
function dinerOwnerIds(){return [...new Set([...data.menuEntitlements.map(row=>row.ownerId),...data.menuRequests.map(row=>row.ownerId)].filter(Boolean))]}
async function loadDinerOrders(force=false){
  if(data.dinerOrdersLoaded&&!force)return;
  const ownerIds=dinerOwnerIds();
  const perOwner=await Promise.all(ownerIds.map(ownerId=>api.list(dinerOrderKind(ownerId)).catch(()=>[])));
  data.dinerOrders=perOwner.flat().filter(row=>!row.tokenReservation);
  data.dinerOrdersLoaded=true;
}
function downloadFile(name,contents,type='text/plain'){const url=URL.createObjectURL(new Blob([contents],{type})),link=document.createElement('a');link.href=url;link.download=name;document.body.appendChild(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function csvCell(value){const text=String(value??'');return /[",\n]/.test(text)?`"${text.replace(/"/g,'""')}"`:text}
function dinerSummaries(fromDate,toDate){
  const rows=data.dinerOrders.filter(order=>{
    if(['Rejected','Payment Rejected'].includes(order.status))return false;
    const day=dinerIndiaDate(order.createdAt);
    if(fromDate&&day<fromDate)return false;
    if(toDate&&day>toDate)return false;
    return true;
  });
  const byPhone=new Map();
  rows.forEach(order=>{
    const phone=normaliseDinerPhone(order.phone);
    if(!phone)return;
    const entry=byPhone.get(phone)||{phone,name:'',restaurants:new Set(),orders:0,totalSpent:0,lastOrderAt:''};
    entry.name=order.customerName||order.customer||entry.name;
    entry.restaurants.add(order.restaurantId||'');
    entry.orders+=1;
    entry.totalSpent+=Number(order.total)||0;
    if(!entry.lastOrderAt||new Date(order.createdAt)>new Date(entry.lastOrderAt))entry.lastOrderAt=order.createdAt;
    byPhone.set(phone,entry);
  });
  return [...byPhone.values()].sort((a,b)=>new Date(b.lastOrderAt)-new Date(a.lastOrderAt));
}
function diners(){
  $('#page').innerHTML=`<div class="section-head"><div><h1>Customer Details</h1><p class="muted">Loading customer order history across all restaurants…</p></div></div>`;
  loadDinerOrders().then(drawDiners).catch(error=>{$('#page').innerHTML=`<div class="section-head"><div><h1>Customer Details</h1><p class="muted">Could not load customer data.</p></div></div><div class="card">${esc(error.message||'Unknown error')}</div>`});
}
function drawDiners(){
  const fromInput=$('#dinerFrom')?.value||'',toInput=$('#dinerTo')?.value||'';
  const summaries=dinerSummaries(fromInput,toInput);
  $('#page').innerHTML=`<div class="section-head"><div><h1>Customer Details</h1><p class="muted">${data.dinerOrders.length} order(s) across ${dinerOwnerIds().length} restaurant account(s), grouped by phone number.</p></div><button class="btn" id="refreshDiners">Refresh</button></div><div class="diner-filter-bar"><label>From<input id="dinerFrom" type="date" value="${esc(fromInput)}"></label><label>To<input id="dinerTo" type="date" value="${esc(toInput)}"></label><button class="btn secondary" id="clearDinerDates">Clear dates</button><button class="btn" id="exportDinerCsv">Export CSV</button></div><div class="grid stats">${metric('Customers',summaries.length)}${metric('Orders in period',summaries.reduce((sum,row)=>sum+row.orders,0))}${metric('Revenue in period',money(summaries.reduce((sum,row)=>sum+row.totalSpent,0)))}</div><div class="card table-wrap"><table><thead><tr><th>Phone</th><th>Customer name</th><th>Restaurants ordered from</th><th>Orders</th><th>Total spent</th><th>Last order</th></tr></thead><tbody>${summaries.map(row=>`<tr><td>${esc(row.phone)}</td><td>${esc(row.name||'Guest')}</td><td>${row.restaurants.size}</td><td>${row.orders}</td><td>${money(row.totalSpent)}</td><td>${row.lastOrderAt?new Date(row.lastOrderAt).toLocaleString('en-IN',{dateStyle:'medium',timeStyle:'short'}):''}</td></tr>`).join('')||'<tr><td colspan="6">No customers in this period.</td></tr>'}</tbody></table></div>`;
  $('#dinerFrom').onchange=drawDiners;$('#dinerTo').onchange=drawDiners;
  $('#clearDinerDates').onclick=()=>{$('#dinerFrom').value='';$('#dinerTo').value='';drawDiners()};
  $('#refreshDiners').onclick=async()=>{$('#refreshDiners').disabled=true;await loadDinerOrders(true);drawDiners()};
  $('#exportDinerCsv').onclick=()=>{
    const header=['Phone','Customer Name','Restaurants Ordered From','Orders','Total Spent (INR)','Last Order'];
    const lines=[header.map(csvCell).join(',')];
    summaries.forEach(row=>lines.push([row.phone,row.name||'Guest',row.restaurants.size,row.orders,row.totalSpent.toFixed(2),row.lastOrderAt?new Date(row.lastOrderAt).toISOString():''].map(csvCell).join(',')));
    const suffix=fromInput||toInput?`_${fromInput||'start'}_to_${toInput||'now'}`:'_all';
    downloadFile(`g58-customers${suffix}.csv`,lines.join('\r\n'),'text/csv;charset=utf-8');
    toast(`Exported ${summaries.length} customer(s) to CSV`);
  };
}
function digit58(){
  const stores=[...data.digit58Stores].sort((a,b)=>new Date(b.createdAt||b.$createdAt)-new Date(a.createdAt||a.$createdAt));
  const owners=new Set(stores.map(row=>row.ownerId)).size;
  $('#page').innerHTML=`<div class="section-head"><div><h1>Digit58</h1><p class="muted">Stores that have gone digital on Digit58 — store profiles, categories and owners.</p></div></div><div class="grid stats">${metric('Stores',stores.length)}${metric('Store Owners',owners)}${metric('Categories',new Set(stores.map(row=>row.category||'General store')).size)}${metric('Newest Store',stores[0]?new Date(stores[0].createdAt||stores[0].$createdAt).toLocaleDateString('en-IN',{dateStyle:'medium'}):'—')}</div><div class="admin-filter-bar"><input id="digit58Search" placeholder="Search store, category or owner email"><select id="digit58Category"><option value="All">All categories</option>${[...new Set(stores.map(row=>row.category||'General store'))].map(category=>`<option>${esc(category)}</option>`).join('')}</select></div><div class="card table-wrap"><table><thead><tr><th>Store</th><th>Category</th><th>City</th><th>Owner</th><th>Created</th></tr></thead><tbody id="digit58Rows">${stores.map(digit58Row).join('')||'<tr><td colspan="5">No Digit58 stores yet.</td></tr>'}</tbody></table></div>`;
  const draw=()=>{const q=$('#digit58Search').value.toLowerCase(),category=$('#digit58Category').value,rows=stores.filter(row=>(category==='All'||row.category===category)&&`${row.storeName} ${row.category} ${row.ownerEmail}`.toLowerCase().includes(q));$('#digit58Rows').innerHTML=rows.map(digit58Row).join('')||'<tr><td colspan="5">No matching stores.</td></tr>'};
  $('#digit58Search').oninput=draw;$('#digit58Category').onchange=draw;
}
function digit58Row(row){return `<tr><td><strong>${esc(row.storeName||'Store')}</strong></td><td>${esc(row.category||'General store')}</td><td>${esc(row.city||'')}</td><td>${esc(row.ownerEmail||row.ownerId||'')}</td><td>${row.createdAt?new Date(row.createdAt).toLocaleDateString('en-IN',{dateStyle:'medium'}):''}</td></tr>`}
function marketplace(){$('#page').innerHTML=`<div class="section-head"><div><h1>Public Posts & Business Cards</h1><p class="muted">Edit records or select multiple entries for permanent deletion.</p></div><button class="btn red" id="deleteSelected">Delete selected</button></div><div class="tabs"><button class="btn small" data-market="customer">Customer posts (${data.customers.length})</button><button class="btn small secondary" data-market="business">Business cards (${data.businesses.length})</button></div><div class="card table-wrap" id="marketTable" style="margin-top:14px"></div>`;let type='customer';const draw=()=>{const rows=type==='customer'?data.customers:data.businesses;$('#marketTable').innerHTML=`<table><thead><tr><th></th><th>Title</th><th>Location</th><th>Account</th><th>Status</th><th>Action</th></tr></thead><tbody>${rows.map(row=>`<tr><td><input type="checkbox" data-post-id="${esc(row.id)}"></td><td>${esc(row.title)}</td><td>${esc(row.district||row.city||'')}</td><td>${esc(row.accountEmail||row.email||'')}</td><td>${row.blocked?'Blocked':'Active'}</td><td><button class="btn small" data-edit-post="${esc(row.id)}">Edit</button></td></tr>`).join('')||'<tr><td colspan="6">No records.</td></tr>'}</tbody></table>`;$$('[data-edit-post]').forEach(button=>button.onclick=()=>editPost(type,button.dataset.editPost))};draw();$$('[data-market]').forEach(button=>button.onclick=()=>{type=button.dataset.market;$$('[data-market]').forEach(item=>item.className='btn small secondary');button.className='btn small';draw()});$('#deleteSelected').onclick=async()=>{const ids=$$('[data-post-id]:checked').map(input=>input.dataset.postId);if(!ids.length||!confirm(`Delete ${ids.length} selected record(s)?`))return;if(type==='customer')data.customers=data.customers.filter(row=>!ids.includes(row.id));else data.businesses=data.businesses.filter(row=>!ids.includes(row.id));await savePosts();marketplace()}}
function editPost(type,id){const post=(type==='customer'?data.customers:data.businesses).find(row=>String(row.id)===String(id));if(!post)return;modal('Edit Public Record',`<form id="editPostForm"><div class="field"><label>Title</label><input name="title" value="${esc(post.title||'')}" required></div><div class="field"><label>Description</label><textarea name="description" required>${esc(post.description||'')}</textarea></div><div class="form-grid"><div class="field"><label>State</label><input name="state" value="${esc(post.state||'')}"></div><div class="field"><label>District / City</label><input name="district" value="${esc(post.district||post.city||'')}"></div></div><button class="btn full">Save Changes</button></form>`,()=>{$('#editPostForm').onsubmit=async event=>{event.preventDefault();const values=Object.fromEntries(new FormData(event.target));Object.assign(post,values,{city:values.district});await savePost(post,type);closeModal();marketplace();toast('Public record updated')}})}
async function savePost(post,type){if(data.legacyPostDocument)return savePosts();const row=data.postRows.find(item=>String(item.recordKey)===String(post.id));if(!row)throw new Error('Post record not found');const updated=await api.update('posts',row.id,{postType:type,userId:row.userId||post.userId||'',payload:JSON.stringify(post),updatedAt:now()});Object.assign(row,updated)}
async function savePosts(){if(data.legacyPostDocument){await api.update('posts',data.legacyPostDocument.id,{recordKey:'global',customers:JSON.stringify(data.customers),businesses:JSON.stringify(data.businesses),updatedAt:now()});return}const desired=new Set([...data.customers,...data.businesses].map(post=>String(post.id)));for(const row of [...data.postRows]){if(!desired.has(String(row.recordKey))){await api.remove('posts',row.id);data.postRows=data.postRows.filter(item=>item.id!==row.id)}}}
function accounts(){$('#page').innerHTML=`<div class="section-head"><div><h1>Advertising Accounts</h1><p class="muted">Review and block profiles from posting or booking.</p></div></div><div class="card table-wrap"><table><thead><tr><th>Name</th><th>Email</th><th>Phone</th><th>Location</th><th>Status</th><th>Action</th></tr></thead><tbody>${data.profiles.map(row=>`<tr><td>${esc(row.name||'')}</td><td>${esc(row.email||'')}</td><td>${esc(row.phone||'')}</td><td>${esc([row.district,row.state].filter(Boolean).join(', '))}</td><td>${row.blocked?'Blocked':'Active'}</td><td><button class="btn small ${row.blocked?'green':'red'}" data-block="${row.id}">${row.blocked?'Unblock':'Block'}</button></td></tr>`).join('')||'<tr><td colspan="6">No profiles.</td></tr>'}</tbody></table></div>`;$$('[data-block]').forEach(button=>button.onclick=async()=>{const row=data.profiles.find(item=>item.id===button.dataset.block);await api.update('profiles',row.id,{blocked:!row.blocked});await refresh()})}
function slots(){$('#page').innerHTML=`<div class="section-head"><div><h1>Restaurant Ad Placements</h1><p class="muted">Pause deleted or unavailable restaurants so advertisers cannot target them.</p></div></div><div class="grid restaurant-grid">${data.slots.map(row=>`<article class="card"><h3>${esc(row.name)}</h3><p>${esc(row.city)}</p><code>${esc(row.restaurantKey)}</code><div class="chips"><span class="chip">${row.active?'Active':'Paused'}</span></div><button class="btn small ${row.active?'red':'green'}" data-toggle-slot="${row.id}">${row.active?'Pause placement':'Activate placement'}</button></article>`).join('')||'<div class="empty">No registered placements.</div>'}</div>`;$$('[data-toggle-slot]').forEach(button=>button.onclick=async()=>{const row=data.slots.find(item=>item.id===button.dataset.toggleSlot);await api.update('slots',row.id,{active:!row.active});await refresh()})}
async function refresh(){await loadData();shell()}
function modal(title,body,ready){document.body.insertAdjacentHTML('beforeend',`<div class="modal-backdrop" id="modal"><section class="modal"><div class="section-head"><h2>${title}</h2><button class="btn small secondary" id="close">✕</button></div>${body}</section></div>`);$('#close').onclick=closeModal;ready?.()}
function closeModal(){$('#modal')?.remove()}
setInterval(()=>$$('[data-expires]').forEach(node=>node.textContent=timeLeft(node.dataset.expires,node.dataset.lifetime==='true')),30000);
boot();
